") comment_opt in let sh (k,v,comment) = Printf.sprintf "%s%s=%s; export %s;
" (make_comment comment) k v k in let csh (k,v,comment) = if unconditional then Printf.sprintf "%ssetenv %s %s
" (make_comment comment) k v else Printf.sprintf "%sif ( ! ${?%s} ) setenv %s ""
setenv %s %s
" (make_comment comment) k k k v in let fish (k,v,comment) = (* Fish converts some colon-separated vars to arrays, which have to be treated differently. MANPATH is handled automatically, so better not to set it at all when not already defined *) let to_arr_string v = OpamStd.List.concat_map " " (fun v -> if v = Printf.sprintf ""$%s"" k then "$"^k (* remove quotes *) else v) (OpamStd.String.split v ':') in match k with | "PATH" -> Printf.sprintf "%sset -gx %s %s;
" (make_comment comment) k (to_arr_string v) | "MANPATH" -> Printf.sprintf "%sif [ (count $%s) -gt 0 ]; set -gx %s %s; end;
" (make_comment comment) k k (to_arr_string v) | _ -> (* Regular string variables *) Printf.sprintf "%sset -gx %s %s;
" (make_comment comment) k v in let pwsh (k,v,comment) = Printf.sprintf "%s$env:%s=%s
" (make_comment comment) k v in let cmd (k,v,comment) = let make_cmd_comment comment_opt = OpamStd.Option.to_string (Printf.sprintf ":: %s
") comment_opt in Printf.sprintf "%sset "%s=%s"
" (make_cmd_comment comment) k v in match shell with | SH_zsh | SH_bash | SH_sh -> sh | SH_fish -> fish | SH_csh -> csh | SH_pwsh _ -> pwsh | SH_cmd -> cmd

